"""The classes of the results by group and by owner (reference/results §1), generated by
scripts/gen_result_views.py from the result tree of the engine: do not edit. Each property is the
engine's selection of a quantity for the owner of the view (``Results._select``): the whole
array, a slice of it where the rows are contiguous, else a read-only copy of the rows; None when
not computed. What a class has beyond the tree is in its hand-written base (``_result_extras``)."""

# fmt: off
from __future__ import annotations

import numpy as np

from ._result_extras import _BodyExtras, _OwnerList, _OwnerView, _ResultsExtras, _View


class ExcitationResults(_View):
    """The exciting forces per wave amplitude by method (the excitation_* quantities): diffraction (by pressure
    integration), froude_krylov and scattering [F, H, D], haskind [F, H, K] (by the Haskind relation)."""

    __slots__ = ()

    @property
    def diffraction(self) -> np.ndarray | None:
        """[F, H, D] (of a body [F, H, D_b]) exciting force by pressure integration, per wave amplitude.

        ``excitation_diffraction`` (complex64; N m^r_i per m), rule coordinates; None when not computed."""
        return self._get("excitation.diffraction")

    @property
    def froude_krylov(self) -> np.ndarray | None:
        """[F, H, D] (of a body [F, H, D_b]) Froude-Krylov force, per wave amplitude.

        ``excitation_froude_krylov`` (complex64; N m^r_i per m), rule coordinates; None when not computed."""
        return self._get("excitation.froude_krylov")

    @property
    def scattering(self) -> np.ndarray | None:
        """[F, H, D] (of a body [F, H, D_b]) scattering force, per wave amplitude.

        ``excitation_scattering`` (complex64; N m^r_i per m), rule coordinates; None when not computed."""
        return self._get("excitation.scattering")

    @property
    def haskind(self) -> np.ndarray | None:
        """[F, H, K] (of a body [F, H, K_b]) exciting force by the Haskind relation, per wave amplitude.

        ``excitation_haskind`` (complex64; N m^r_k per m), rule coordinates; None when not computed."""
        return self._get("excitation.haskind")


