    __slots__ = ()

    @property
    def points(self) -> np.ndarray | None:
        """[N, 3] (of a body [N_b, 3]) the body output points (global).

        ``body_points`` (float64; m), rule body_points; None when not computed."""
        return self._get("body_points.points")

    @property
    def ids(self) -> np.ndarray | None:
        """[N, 4] (of a body [N_b, 4]) body (zero-based), element or point (one-based), sx, sy of each body output
        point.

        ``body_points_ids`` (int32), rule body_points; None when not computed."""
        return self._get("body_points.ids")

    @property
    def normals(self) -> np.ndarray | None:
        """[N, 3] (of a body [N_b, 3]) unit normals into the fluid at the body output points (global).

        ``body_points_normals`` (float64), rule body_points; None when not computed."""
        return self._get("body_points.normals")

    @property
    def areas(self) -> np.ndarray | None:
        """[N] (of a body [N_b]) the area of each body output point.

        ``body_points_areas`` (float64; m^2), rule body_points; None when not computed."""
        return self._get("body_points.areas")

    @property
    def pressure_radiation(self) -> np.ndarray | None:
        """[F, N, K] (of a body [F, N_b, K]) p/(rho g) on the body per unit displacement of the column.

        ``body_points_pressure_radiation`` (complex64; m per m^r_k), rule body_points; None when not computed."""
        return self._get("body_points.pressure_radiation")

    @property
    def pressure_diffraction(self) -> np.ndarray | None:
        """[F, N, H] (of a body [F, N_b, H]) p/(rho g) on the body of the total diffraction potential, per wave
        amplitude.

        ``body_points_pressure_diffraction`` (complex64; m per m), rule body_points; None when not computed."""
        return self._get("body_points.pressure_diffraction")

    @property
    def velocity_radiation(self) -> np.ndarray | None:
        """[F, N, K, 3] (of a body [F, N_b, K, 3]) fluid velocity on the body per unit displacement of the column
        (global axes).

        ``body_points_velocity_radiation`` (complex64; m/s per m^r_k), rule body_points; None when not computed."""
        return self._get("body_points.velocity_radiation")

    @property
    def velocity_diffraction(self) -> np.ndarray | None:
        """[F, N, H, 3] (of a body [F, N_b, H, 3]) fluid velocity on the body of the total diffraction potential, per
        wave amplitude (global axes).

        ``body_points_velocity_diffraction`` (complex64; m/s per m), rule body_points; None when not computed."""
        return self._get("body_points.velocity_diffraction")


