class DriftResults(_View):
    """The mean drifts by method (the drift_* quantities), of the heading pairs heading_pairs [P, 2] (deg): (beta,
    beta) of every heading, or every pair beta_a <= beta_b with second_order.drift_bidirectional; complex (the
    coefficient of a pair of two headings is complex, of equal headings real)."""

    __slots__ = ()

    @property
    def pressure_integration(self) -> np.ndarray | None:
        """[F, P, D] (of a body [F, P, D_b]) mean drift by pressure integration on the coordinates, of the wave pairs
        (omega, beta_a), (omega, beta_b) of drift_heading_pairs: the force and moment about the rotation centre R
        (body axes) on the rigid coordinates, the generalized force on the generalized ones (the work of the
        pressure on the exact surface against the mode shape); NaN on the pressure coordinates.

        ``drift_pressure_integration`` (complex128; N m^r_i per m^2), rule coordinates; None when not computed."""
        return self._get("drift.pressure_integration")

    @property
    def pressure_integration_body_axes(self) -> np.ndarray | None:
        """[F, P, 3 B] (of a body [F, P, 3]) the pressure drift moment about the moving rotation centre R of each body
        (body axes); equal headings only (NaN for the other pairs).

        ``drift_pressure_integration_body_axes`` (complex128; N m per m^2), rule columns; None when not computed."""
        return self._get("drift.pressure_integration_body_axes")

    @property
    def control_surface(self) -> np.ndarray | None:
        """[F, P, D] (of a body [F, P, D_b]) mean drift by the control surface on the coordinates, of the heading
        pairs: the force and moment about the rotation centre R (body axes) on the rigid coordinates; NaN on the
        generalized and pressure coordinates.

        ``drift_control_surface`` (complex128; N m^r_i per m^2), rule coordinates; None when not computed."""
        return self._get("drift.control_surface")

    @property
    def control_surface_body_axes(self) -> np.ndarray | None:
        """[F, P, 3 B] (of a body [F, P, 3]) the control-surface drift moment about the moving rotation centre R of
        each body (body axes); equal headings only (NaN for the other pairs).

        ``drift_control_surface_body_axes`` (complex128; N m per m^2), rule columns; None when not computed."""
        return self._get("drift.control_surface_body_axes")

    @property
    def momentum_conservation(self) -> np.ndarray | None:
        """[F, P, 3] (None for a body) mean drift by momentum conservation (global axes; the far-field total of all
        bodies): surge, sway force, yaw moment about the global z axis, of the heading pairs.

        ``drift_momentum_conservation`` (complex128; N per m^2, N m per m^2), rule global; None when not computed."""
        return self._get("drift.momentum_conservation")

    @property
    def heading_pairs(self) -> np.ndarray | None:
        """[P, 2] the heading pairs (beta_a, beta_b) of the drifts: (beta, beta) for unidirectional, every pair beta_a
        <= beta_b (heading order) for bidirectional.

        ``drift_heading_pairs`` (float64; deg), rule shared; None when not computed."""
        return self._get("drift.heading_pairs")


class QtfResults(_View):
    """The QTFs by part and method (the qtf_* quantities), of the heading pairs heading_pairs [P, 2] (deg):
    quadratic.pressure_integration, quadratic.control_surface, potential.direct, potential.indirect, each with
    difference and sum [F, F, P, D] on the coordinates; newman.<drift method>, Newman's approximation difference [F,
    F, H, D] of the equal headings (momentum conservation [F, F, H, 3])."""

    __slots__ = ()

    @property
    def quadratic(self) -> QtfQuadraticResults:
        """The quadratic part of the QTFs: by pressure integration and by the control surface."""
        return QtfQuadraticResults(self._res, self._body)

    @property
    def potential(self) -> QtfPotentialResults:
        """The force of the second-order potential: by the direct and the indirect method."""
        return QtfPotentialResults(self._res, self._body)

    @property
    def newman(self) -> QtfNewmanResults:
        """Newman's approximation of the difference-frequency QTF, by the method of its mean drift:
        pressure_integration, control_surface, momentum_conservation."""
        return QtfNewmanResults(self._res, self._body)

    @property
    def heading_pairs(self) -> np.ndarray | None:
        """[P, 2] the heading pairs (beta_a, beta_b) of the QTFs: (beta, beta) for unidirectional, every pair beta_a <=
        beta_b (heading order) for bidirectional.

        ``qtf_heading_pairs`` (float64; deg), rule shared; None when not computed."""
        return self._get("qtf.heading_pairs")


class QtfQuadraticResults(_View):
    """The quadratic part of the QTFs: by pressure integration and by the control surface."""

    __slots__ = ()

    @property
    def pressure_integration(self) -> QtfQuadraticPressureIntegrationResults:
        """The quadratic QTF by pressure integration at the difference and the sum frequencies."""
        return QtfQuadraticPressureIntegrationResults(self._res, self._body)

    @property
    def control_surface(self) -> QtfQuadraticControlSurfaceResults:
        """The quadratic QTF by the control surface at the difference and the sum frequencies."""
        return QtfQuadraticControlSurfaceResults(self._res, self._body)


class QtfQuadraticPressureIntegrationResults(_View):
    """The quadratic QTF by pressure integration at the difference and the sum frequencies."""

    __slots__ = ()

    @property
    def difference(self) -> np.ndarray | None:
        """[F, F, P, D] (of a body [F, F, P, D_b]) quadratic QTF by pressure integration at the difference frequency of
        the waves (omega_a, beta_a), (omega_b, beta_b) of qtf_heading_pairs: the coefficient of A_a A_b* exp(i
        (omega_a - omega_b) t) on the coordinates (the force and moment about the rotation centre R in body axes,
        the generalized forces; NaN on the pressure coordinates).

        ``qtf_quadratic_pressure_integration_difference`` (complex128; N m^r_i per m^2), rule coordinates; None when
        not computed."""
        return self._get("qtf.quadratic.pressure_integration.difference")

    @property
    def sum(self) -> np.ndarray | None:
        """[F, F, P, D] (of a body [F, F, P, D_b]) quadratic QTF by pressure integration at the sum frequency: the
        coefficient of A_a A_b exp(i (omega_a + omega_b) t) on the coordinates (the force and moment about the
        rotation centre R in body axes, the generalized forces; NaN on the pressure coordinates).

        ``qtf_quadratic_pressure_integration_sum`` (complex128; N m^r_i per m^2), rule coordinates; None when not
        computed."""
        return self._get("qtf.quadratic.pressure_integration.sum")


