class QtfNewmanResults(_View):
    """Newman's approximation of the difference-frequency QTF, by the method of its mean drift: pressure_integration,
    control_surface, momentum_conservation."""

    __slots__ = ()

    @property
    def pressure_integration(self) -> QtfNewmanPressureIntegrationResults:
        """Newman's approximation from the mean drift by pressure integration."""
        return QtfNewmanPressureIntegrationResults(self._res, self._body)

    @property
    def control_surface(self) -> QtfNewmanControlSurfaceResults:
        """Newman's approximation from the mean drift by the control surface."""
        return QtfNewmanControlSurfaceResults(self._res, self._body)

    @property
    def momentum_conservation(self) -> QtfNewmanMomentumConservationResults:
        """Newman's approximation from the mean drift by momentum conservation (of all bodies, global axes)."""
        return QtfNewmanMomentumConservationResults(self._res, self._body)


