class HydrostaticsResults(_View):
    """The hydrostatics of every body of the solve [B, ...] (a body's: bodies[b].hydrostatics)."""

    __slots__ = ()

    @property
    def volumes(self) -> np.ndarray | None:
        """[B, 3] the three estimates of the volume of each body by the divergence theorem (the integrals of x n_x, y
        n_y, z n_z).

        ``hydrostatics_volumes`` (float64; m^3), rule global; None when not computed."""
        return self._get("hydrostatics.volumes")

    @property
    def volume(self) -> np.ndarray | None:
        """[B] the volume of each body: the mean of its three estimates (volumes).

        ``hydrostatics_volume`` (float64; m^3), rule global; None when not computed."""
        return self._get("hydrostatics.volume")

    @property
    def displaced_mass(self) -> np.ndarray | None:
        """[B] rho V of each body with V the x estimate of the volume, volumes[0] (the mass of a body whose mass is
        'displaced', before the fluid of its tanks).

        ``hydrostatics_displaced_mass`` (float64; kg), rule global; None when not computed."""
        return self._get("hydrostatics.displaced_mass")

    @property
    def center_of_buoyancy(self) -> np.ndarray | None:
        """[B, 3] the centre of buoyancy of each body (body coordinates).

        ``hydrostatics_center_of_buoyancy`` (float64; m), rule global; None when not computed."""
        return self._get("hydrostatics.center_of_buoyancy")

    @property
    def waterplane_area(self) -> np.ndarray | None:
        """[B] the water-plane area of each body.

        ``hydrostatics_waterplane_area`` (float64; m^2), rule global; None when not computed."""
        return self._get("hydrostatics.waterplane_area")

    @property
    def waterplane_centroid(self) -> np.ndarray | None:
        """[B, 2] the centroid (x, y) of the water plane of each body (body coordinates).

        ``hydrostatics_waterplane_centroid`` (float64; m), rule global; None when not computed."""
        return self._get("hydrostatics.waterplane_centroid")

    @property
    def stiffness_rho_g(self) -> np.ndarray | None:
        """[B, 6, 6] the hydrostatic stiffness of each body, rho g terms only (body axes about R).

        ``hydrostatics_stiffness_rho_g`` (float64; SI), rule global; None when not computed."""
        return self._get("hydrostatics.stiffness_rho_g")

    @property
    def mass(self) -> np.ndarray | None:
        """[B] the mass of each body: given, or rho volumes[0] less the fluid of its tanks for 'displaced'; NaN without
        a mass.

        ``hydrostatics_mass`` (float64; kg), rule global; None when not computed."""
        return self._get("hydrostatics.mass")

    @property
    def center_of_gravity(self) -> np.ndarray | None:
        """[B, 3] the centre of gravity G of each body (body coordinates, as the input); NaN without G (no weight
        terms).

        ``hydrostatics_center_of_gravity`` (float64; m), rule global; None when not computed."""
        return self._get("hydrostatics.center_of_gravity")

    @property
    def stiffness(self) -> np.ndarray | None:
        """[B, 6, 6] the hydrostatic stiffness of each body with the weight terms (body axes about R).

        ``hydrostatics_stiffness`` (float64; SI), rule global; None when not computed."""
        return self._get("hydrostatics.stiffness")

    @property
    def metacentric_height(self) -> np.ndarray | None:
        """[B, 2] the metacentric heights GM in roll and pitch of each body: C44 and C55 with the weight terms over rho
        g volumes[0]; NaN without the weight (no mass or no G) or without a volume (a body of sheets or plates
        only).

        ``hydrostatics_metacentric_height`` (float64; m), rule global; None when not computed."""
        return self._get("hydrostatics.metacentric_height")


class PressureSurfaceResults(_OwnerView):
    """The outputs of one pressure surface of a body at its points (the rows of the pressure_surfaces_* quantities
    whose pressure_surfaces_ids is it), by name or position."""

    __slots__ = ()

    @property
    def points(self) -> np.ndarray | None:
        """[Q_s, 3] the pressure-surface points (global).

        ``pressure_surfaces`` (float64; m), rule pressure_surface; None when not computed."""
        return self._get("pressure_surfaces.points")

    @property
    def elevation_radiation(self) -> np.ndarray | None:
        """[F, Q_s, K] pressure-surface elevation per unit coordinate of the column.

        ``pressure_surfaces_elevation_radiation`` (complex64; m per unit coordinate), rule pressure_surface; None
        when not computed."""
        return self._get("pressure_surfaces.elevation_radiation")

    @property
    def elevation_diffraction(self) -> np.ndarray | None:
        """[F, Q_s, H] pressure-surface elevation of the total diffraction potential, per wave amplitude.

        ``pressure_surfaces_elevation_diffraction`` (complex64; m per m), rule pressure_surface; None when not
        computed."""
        return self._get("pressure_surfaces.elevation_diffraction")


class TankResults(_OwnerView):
    """The outputs of one tank of a body at its points (the rows of the tanks_* quantities whose tanks_ids is it), by
    name or position; radiation only (the fluid of a tank has no incident or scattered wave)."""

    __slots__ = ()

    @property
    def points(self) -> np.ndarray | None:
        """[M_t, 3] the points in the tanks (body axes): the field_points of each tank of the model solved, the tanks
        of the bodies in order.

        ``tanks`` (float64; m), rule tank; None when not computed."""
        return self._get("tanks.points")

    @property
    def pressure_radiation(self) -> np.ndarray | None:
        """[F, M_t, K] elevation or p/(rho g) of the tank fluid at the tank points per unit displacement of the column
        (the columns of the tank's body; zero for the others).

        ``tanks_pressure_radiation`` (complex64; m per m^r_k), rule tank; None when not computed."""
        return self._get("tanks.pressure_radiation")

    @property
    def velocity_radiation(self) -> np.ndarray | None:
        """[F, M_t, K, 3] velocity of the tank fluid at the tank points per unit displacement of the column (global
        axes; the columns of the tank's body, zero for the others).

        ``tanks_velocity_radiation`` (complex64; m/s per m^r_k), rule tank; None when not computed."""
        return self._get("tanks.velocity_radiation")


class BodyResults(_BodyExtras):
    """The results of one body (``results.bodies[name]``): views of the global arrays, read-only, None when not
    computed. D_b its coordinates, K_b its radiation columns, N_b its body points; the coupled coefficients between
    bodies stay on the results; its pressure surfaces and tanks are lists of it. Its ``index``, ``name``,
    ``coordinates`` and ``hydrostatics`` are those of its base ``_BodyExtras``."""

    __slots__ = ()

    @property
    def added_mass(self) -> np.ndarray | None:
        """[F, D_b, K_b] added mass.

        ``added_mass`` (float32; kg m^(r_i+r_j)), rule coordinates; None when not computed."""
        return self._get("added_mass")

    @property
    def radiation_damping(self) -> np.ndarray | None:
        """[F, D_b, K_b] radiation damping.

        ``radiation_damping`` (float32; kg/s m^(r_i+r_j)), rule coordinates; None when not computed."""
        return self._get("radiation_damping")

    @property
    def added_mass_zero_frequency(self) -> np.ndarray | None:
        """[D_b, K_b] added mass at omega = 0.

        ``added_mass_zero_frequency`` (float32; kg m^(r_i+r_j)), rule coordinates; None when not computed."""
        return self._get("added_mass_zero_frequency")

    @property
    def added_mass_infinite_frequency(self) -> np.ndarray | None:
        """[D_b, K_b] added mass at omega = inf.

        ``added_mass_infinite_frequency`` (float32; kg m^(r_i+r_j)), rule coordinates; None when not computed."""
        return self._get("added_mass_infinite_frequency")

    @property
    def excitation(self) -> ExcitationResults:
        """The exciting forces per wave amplitude by method (the excitation_* quantities): diffraction (by pressure
        integration), froude_krylov and scattering [F, H, D], haskind [F, H, K] (by the Haskind relation)."""
        return ExcitationResults(self._res, self._body)

    @property
    def motion(self) -> np.ndarray | None:
        """[F, H, D_b] motion (RAO): m/m, rad/m.

        ``motion`` (complex64; m^(1-r_i) per m), rule coordinates; None when not computed."""
        return self._get("motion")

    @property
    def mode_restoring(self) -> np.ndarray | None:
        """[D_b, D_b] the computed restoring of the generalized and pressure coordinates (hydrostatic and pressure-
        surface) and the stiffness of the pressure modes; not the body's mode_stiffness, an input.

        ``mode_restoring`` (float64; SI (N m^(r_i+r_j-1) for rigid coordinates)), rule coordinates; None when not
        computed."""
        return self._get("mode_restoring")

    @property
    def pressure_mode_damping(self) -> np.ndarray | None:
        """[D_b, D_b] the computed damping of the pressure modes (pneumatic), zero for the other coordinates; the
        body's mode_damping is an input.

        ``pressure_mode_damping`` (float64; SI (kg/s m^(r_i+r_j) for rigid coordinates)), rule coordinates; None
        when not computed."""
        return self._get("pressure_mode_damping")

    @property
    def body_points(self) -> BodyPointResults:
        """The outputs on the bodies at the body output points (the body_points_* quantities): the points, their ids,
        normals and areas, the pressures and velocities."""
        return BodyPointResults(self._res, self._body)

    @property
    def pressure_surfaces(self) -> _OwnerList:
        """The outputs of one pressure surface of a body at its points (the rows of the pressure_surfaces_* quantities
        whose pressure_surfaces_ids is it), by name or position. A list of ``PressureSurfaceResults``, by name or
        position."""
        return self._res._owner_list("pressure_surfaces", self._body, PressureSurfaceResults)

    @property
    def tanks(self) -> _OwnerList:
        """The outputs of one tank of a body at its points (the rows of the tanks_* quantities whose tanks_ids is it),
        by name or position; radiation only (the fluid of a tank has no incident or scattered wave). A list of
        ``TankResults``, by name or position."""
        return self._res._owner_list("tanks", self._body, TankResults)

    @property
    def drift(self) -> DriftResults:
        """The mean drifts by method (the drift_* quantities), of the heading pairs heading_pairs [P, 2] (deg): (beta,
        beta) of every heading, or every pair beta_a <= beta_b with second_order.drift_bidirectional; complex (the
        coefficient of a pair of two headings is complex, of equal headings real)."""
        return DriftResults(self._res, self._body)

    @property
    def qtf(self) -> QtfResults:
        """The QTFs by part and method (the qtf_* quantities), of the heading pairs heading_pairs [P, 2] (deg):
        quadratic.pressure_integration, quadratic.control_surface, potential.direct, potential.indirect, each with
        difference and sum [F, F, P, D] on the coordinates; newman.<drift method>, Newman's approximation difference
        [F, F, H, D] of the equal headings (momentum conservation [F, F, H, 3])."""
        return QtfResults(self._res, self._body)


class Results(_ResultsExtras):
    """The results of a solve, of a results file, or given as arrays (``Results.of``): the views of the result tree
    (reference/results §1), dimensional (SI, unit wave amplitude), read-only, None when not computed. The axes and
    the quantities read by body are its properties of their names (``omegas``, ``headings``, ``added_mass``,
    ``motion``, ...), the others are in its groups (``excitation``, ``body_points``, ``field_points``, ``kochin``,
    ``drift``, ``qtf``, ``hydrostatics``) and in its owners (``lids[name]``, ``bodies[name]``); a quantity by its
    name: ``quantity(name)`` (the list is ``hb.quantities()``). The first-order quantities are in body axes about
    each body's rotation centre R; the mean drift moments as theory §1.1. Axes: F the ordinary frequencies
    (``omegas``), H the headings (``headings``), D the coordinates (``coordinates``), K the radiation columns
    (``radiation_mode_ids``). Its loading, meta data, coordinates, ``coefficient``, ``coordinate``, ``normalized``,
    ``save`` and ``write_wamit`` are those of its base ``_ResultsExtras``."""

    __slots__ = ()

    @property
    def bodies(self) -> _OwnerList:
        """The results of each body (``BodyResults``: views of the global arrays), by name or position:
        ``results.bodies["spar"].added_mass``."""
        return self._owner_list("bodies", None, BodyResults)

    @property
    def omegas(self) -> np.ndarray | None:
        """[F] the ordinary radian frequencies.

        ``omegas`` (float64; rad/s), rule global; None when not computed."""
        return self._get("omegas")

    @property
    def headings(self) -> np.ndarray | None:
        """[H] the wave headings, counter-clockwise from +x.

        ``headings`` (float64; deg), rule global; None when not computed."""
        return self._get("headings")

    @property
    def radiation_mode_ids(self) -> np.ndarray | None:
        """[K] the one-based coordinate id of each radiation column.

        ``radiation_mode_ids`` (int32), rule global; None when not computed."""
        return self._get("radiation_mode_ids")

    @property
    def added_mass(self) -> np.ndarray | None:
        """[F, D, K] added mass.

        ``added_mass`` (float32; kg m^(r_i+r_j)), rule coordinates; None when not computed."""
        return self._get("added_mass")

    @property
    def radiation_damping(self) -> np.ndarray | None:
        """[F, D, K] radiation damping.

        ``radiation_damping`` (float32; kg/s m^(r_i+r_j)), rule coordinates; None when not computed."""
        return self._get("radiation_damping")

    @property
    def added_mass_zero_frequency(self) -> np.ndarray | None:
        """[D, K] added mass at omega = 0.

        ``added_mass_zero_frequency`` (float32; kg m^(r_i+r_j)), rule coordinates; None when not computed."""
        return self._get("added_mass_zero_frequency")

    @property
    def added_mass_infinite_frequency(self) -> np.ndarray | None:
        """[D, K] added mass at omega = inf.

        ``added_mass_infinite_frequency`` (float32; kg m^(r_i+r_j)), rule coordinates; None when not computed."""
        return self._get("added_mass_infinite_frequency")

    @property
    def excitation(self) -> ExcitationResults:
        """The exciting forces per wave amplitude by method (the excitation_* quantities): diffraction (by pressure
        integration), froude_krylov and scattering [F, H, D], haskind [F, H, K] (by the Haskind relation)."""
        return ExcitationResults(self, None)

    @property
    def motion(self) -> np.ndarray | None:
        """[F, H, D] motion (RAO): m/m, rad/m.

        ``motion`` (complex64; m^(1-r_i) per m), rule coordinates; None when not computed."""
        return self._get("motion")

    @property
    def mode_restoring(self) -> np.ndarray | None:
        """[D, D] the computed restoring of the generalized and pressure coordinates (hydrostatic and pressure-surface)
        and the stiffness of the pressure modes; not the body's mode_stiffness, an input.

        ``mode_restoring`` (float64; SI (N m^(r_i+r_j-1) for rigid coordinates)), rule coordinates; None when not
        computed."""
        return self._get("mode_restoring")

    @property
    def pressure_mode_damping(self) -> np.ndarray | None:
        """[D, D] the computed damping of the pressure modes (pneumatic), zero for the other coordinates; the body's
        mode_damping is an input.

        ``pressure_mode_damping`` (float64; SI (kg/s m^(r_i+r_j) for rigid coordinates)), rule coordinates; None
        when not computed."""
        return self._get("pressure_mode_damping")

    @property
    def body_points(self) -> BodyPointResults:
        """The outputs on the bodies at the body output points (the body_points_* quantities): the points, their ids,
        normals and areas, the pressures and velocities."""
        return BodyPointResults(self, None)

    @property
    def field_points(self) -> FieldPointResults:
        """The outputs at the field points in the sea (the field_points_* quantities): the points, the pressures and
        velocities of the radiation, incident, scattered and total waves."""
        return FieldPointResults(self, None)

    @property
    def lids(self) -> _OwnerList:
        """The outputs of one damping lid at its points (the rows of the lids_* quantities whose lids_ids is it), by
        name or position. A list of ``LidResults``, by name or position."""
        return self._owner_list("lids", None, LidResults)

    @property
    def kochin(self) -> KochinResults:
        """The Kochin functions of the radiation and scattered potentials (theory §11.1), at the angles [A] (rad)."""
        return KochinResults(self, None)

    @property
    def drift(self) -> DriftResults:
        """The mean drifts by method (the drift_* quantities), of the heading pairs heading_pairs [P, 2] (deg): (beta,
        beta) of every heading, or every pair beta_a <= beta_b with second_order.drift_bidirectional; complex (the
        coefficient of a pair of two headings is complex, of equal headings real)."""
        return DriftResults(self, None)

    @property
    def qtf(self) -> QtfResults:
        """The QTFs by part and method (the qtf_* quantities), of the heading pairs heading_pairs [P, 2] (deg):
        quadratic.pressure_integration, quadratic.control_surface, potential.direct, potential.indirect, each with
        difference and sum [F, F, P, D] on the coordinates; newman.<drift method>, Newman's approximation difference
        [F, F, H, D] of the equal headings (momentum conservation [F, F, H, 3])."""
        return QtfResults(self, None)

    @property
    def hydrostatics(self) -> HydrostaticsResults:
        """The hydrostatics of every body of the solve [B, ...] (a body's: bodies[b].hydrostatics)."""
        return HydrostaticsResults(self, None)


